const itemAnns = annotations.filter(a => a.payItemId === item.id && a.type !== 'manual');
for (const ann of itemAnns) {
  const qty = ann.manualQuantity != null ? ann.manualQuantity : (() => {
    if (ann.type === 'count') return 1;
    if (ann.depth && ann.depth > 0) return sfToCY(ann.measurement, ann.depth);
    if (item.unit === 'SY') return sfToSY(ann.measurement);
    return ann.measurement;
  })();
  totalQuantity += qty;
}

const finalize = useCallback(() => {
  if (controlPoints.length < 2) return;
  try {
    const cal = buildGeoCalibration(controlPoints);
    onComplete(cal);
  } catch (err) {
    setGpsError(String(err));
  }
}, [controlPoints, onComplete]);

export function estimateError(cal: GeoCalibration): number {
  let totalErr = 0;
  for (const cp of cal.controlPoints) {
    const projected = gpsToplan(cal, cp.gps);
    const dx = projected.x - cp.plan.x;
    const dy = projected.y - cp.plan.y;
    totalErr += Math.sqrt(dx * dx + dy * dy);
  }
  return totalErr / cal.controlPoints.length;
}
